function dateAdd(key,n){const d=new Date(key+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function weekStart(key){const d=new Date(key+'T12:00:00Z');return dateAdd(key,-((d.getUTCDay()+6)%7))}
function dayLabel(key,options={month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-AU',{timeZone:'UTC',...options}).format(new Date(key+'T12:00:00Z'))}
function localParts(iso,zone=state.zone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return {date:`${p.year}-${p.month}-${p.day}`,hour:+p.hour,minute:+p.minute,time:`${p.hour}:${p.minute}`}}
function localToISO(date,clock,zone='Australia/Sydney'){const target=Date.parse(date+'T'+clock+':00Z');let instant=target;for(let i=0;i<3;i++){const p=localParts(new Date(instant).toISOString(),zone);const observed=Date.parse(p.date+'T'+p.time+':00Z');instant+=target-observed}const result=new Date(instant).toISOString();const check=localParts(result,zone);return check.date===date&&check.time===clock?result:null}
function time(iso,zone=state.zone){return new Intl.DateTimeFormat('en-AU',{timeZone:zone,hour:'numeric',minute:'2-digit',hour12:false}).format(new Date(iso))}
function end(e){return new Date(+new Date(e.start)+e.duration*60000).toISOString()}
function period(){if(state.view==='month'){const start=state.date.slice(0,7)+'-01';const d=new Date(start+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);return [start,dateAdd(d.toISOString().slice(0,10),-1)]}if(state.view==='day')return[state.date,state.date];const s=weekStart(state.date);return[s,dateAdd(s,state.view==='agenda'?6:4)]}
