function calendarPage(){const next=accessible().filter(e=>new Date(e.start)>=NOW).sort((a,b)=>a.start.localeCompare(b.start))[0];const count=accessible().filter(e=>localParts(e.start).date===TODAY).length;return `<div class="heading"><div><div class="eyebrow">Your day, together</div><h1>Calendar</h1><p>One place for your meetings, interviews and everything in between.</p></div><div class="heading-actions">${btn(icon('people')+'Find a time','schedule')}${btn(icon('plus')+'New event','new','primary')}</div></div><div class="summary"><div><span class="tile-icon">${icon('calendar')}</span><div><strong>${count} events today</strong><small>Wednesday, 28 October</small></div>${chip('Your schedule')}</div><div><span class="tile-icon">${icon('clock')}</span><div><strong>${next?'Next · '+esc(next.title):'Nothing coming up'}</strong><small>${next?time(next.start)+' · '+next.duration+' min · '+providerName(next.provider):'Connect your calendar for current availability'}</small></div></div><div><span class="tile-icon">${icon('link')}</span><div><strong>${Number(state.google)+Number(state.microsoft)} connected ${state.google&&state.microsoft?'accounts':'account'}</strong><small>${state.microsoft?'Google & Microsoft':'Google connected · Microsoft available'}</small></div>${btn(icon('arrow'),'connections','ghost','aria-label="Manage calendar connections"')}</div></div>${calendarShell()}`}
function interviewPage(){if(state.persona==='employee')return `<div class="empty">${icon('lock')}<h2>Hiring access is required</h2><p>Your Calendar still shows the events you are permitted to see.</p>${btn('Back to my calendar','calendar','primary')}</div>`;return `<div class="heading"><div><div class="eyebrow">Hiring workspace</div><h1>Interviews</h1><p>Coordinate the panel. Give every candidate a considered experience.</p></div><div class="heading-actions">${btn(icon('calendar')+'Open full calendar','calendar')}${btn(icon('plus')+'Schedule interview','schedule','primary',state.persona==='interviewer'?'disabled title="Recruiter permission required"':'')}</div></div><div class="tabs">${btn(icon('list')+'List','interview-list',state.interviewView==='list'?'active':'')}${btn(icon('calendar')+'Calendar','interview-calendar',state.interviewView==='calendar'?'active':'')}</div><div class="notice">${icon('info')}<div>This is the same calendar, focused on interviews. Availability checks also consider connected calendars, private busy blocks and panel working hours.</div></div>${state.interviewView==='calendar'?calendarShell():`<div class="card table-wrap"><table><thead><tr><th>Candidate / role</th><th>Interview</th><th>When · ${esc(state.zone)}</th><th>Panel</th><th></th></tr></thead><tbody>${accessible().filter(e=>e.type==='interview').map(e=>`<tr><td><b>${esc(e.title.split(' · ')[0])}</b><small>${esc(e.role)}</small></td><td>${esc(e.detail)}</td><td>${dayLabel(localParts(e.start).date)} · ${time(e.start)}</td><td>${e.attendees.length} people</td><td>${btn('View','event:'+e.id,'small')}</td></tr>`).join('')}</tbody></table></div>`}`}
function calendarShell(){return `<section class="calendar-shell" aria-label="Calendar"><aside class="calendar-side">${miniMonth()}<div class="section-label">Show on calendar</div>${Object.entries(categories).filter(([k])=>state.page!=='interviews'||k==='interview').filter(([k])=>state.persona!=='employee'||k!=='interview').map(([k,c])=>`<label class="filter"><input type="checkbox" data-source="${k}" ${state.sources.has(k)?'checked':''}>${c.label}<span class="dot" style="background:${c.color}"></span></label>`).join('')}<p class="source-note">Hiding an event here does not make that time available for booking.</p><div class="side-connections"><div class="section-label" style="margin-top:0">Connected calendars</div><div class="row"><span class="row"><span class="provider">G</span>Google</span><span class="status-dot ${state.google?'':'amber'}" title="${state.google?'Connected in sample':'Disconnected'}"></span></div><div class="row"><span class="row"><span class="provider ms">▦</span>Microsoft</span><small>${state.microsoft?'Connected':'Not connected'}</small></div>${btn('Manage connections '+icon('arrow'),'connections','ghost small')}<p class="source-note">Sample sync · just now<br>Only calendars shared with you.</p></div></aside><div class="calendar-main">${calendarToolbar()}<div id="calendar-results">${calendarView()}</div><div class="calendar-foot"><span>${icon('lock').replace('<svg','<svg style="width:11px;height:11px;vertical-align:middle"')} Details follow your access. Private events stay private.</span><span>${visible().filter(inPeriod).length} events · sample data</span></div></div></section>`}
function miniMonth(){const month=state.date.slice(0,7)+'-01',offset=(new Date(month+'T12:00:00Z').getUTCDay()+6)%7;const next=new Date(month+'T12:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);const days=+dateAdd(next.toISOString().slice(0,10),-1).slice(-2);const w=weekStart(state.date);return `<div class="mini-head">${dayLabel(month,{month:'long',year:'numeric'})}<span class="row">${btn(icon('left'),'mini-prev','ghost icon-btn','aria-label="Previous month"')}${btn(icon('chevron'),'mini-next','ghost icon-btn','aria-label="Next month"')}</span></div><div class="mini">${['M','T','W','T','F','S','S'].map(x=>`<span>${x}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=month.slice(0,8)+String(i+1).padStart(2,'0');return btn(String(i+1),'date:'+d,d===state.date?'chosen':d>=w&&d<=dateAdd(w,4)?'inweek':'',`aria-label="${dayLabel(d,{day:'numeric',month:'long'})}"`)}).join('')}</div>`}
